int main()
{
    static C3DMeshRecord mesh; mesh.m_sphere.Center.X = 1; mesh.m_sphere.Center.Y = 2; mesh.m_sphere.Center.Z = 3; mesh.m_sphere.Radius = 4;
    static CEngineInternalPrimitiveStaticMesh p; p.m_pMesh = &mesh; p.m_scale = 0.5f;
    for (int i = 0; i < 12; ++i) p.m_transform.m[i] = 0;
    p.m_transform.m[0] = 1; p.m_transform.m[4] = 2; p.m_transform.m[8] = 3;      // diagonal scale (1,2,3)
    p.m_transform.m[3] = 10;                                                     // X picks up 10*Y
    p.m_transform.m[9] = 100; p.m_transform.m[10] = 200; p.m_transform.m[11] = 300;
    C3DBoundingSphere out;
    CHECK(p.GetBoundingSphereWorldSpace(out) == true);
    CHECK(out.Center.X == 1 + 20 + 100);
    CHECK(out.Center.Y == 4 + 200);
    CHECK(out.Center.Z == 9 + 300);
    CHECK(out.Radius == 2);
